"use geosolve sketch";
import { sketch, mm } from "@geosolve/sketch-code";

export default sketch({
  title: "Properties",
  dimensions: {
    areKeyConstraintsByDefault: true,
  },
}, ($) => {
  // naïve 東京 🧭 — preserve this comment and source identity.
  const shared = $.parameter("sharedWidth", mm(12), {
    label: "Shared width",
    isKeyParameter: true,
  });
  const spare = $.parameter("spareWidth", mm(12));
  const radius = mm(3);
  const edge = $.geometry.segment("edge", {
    start: [0, 0],
    end: [12, 0],
  });
  const length = $.dimension.curveLength("length", {
    curve: edge.span,
    value: shared,
    label: "Length",
    isKeyConstraint: false,
  });
  const circle = $.geometry.centerRadiusCircle("circle", {
    center: [20, 0],
    radius: radius,
  });
  const size = $.dimension.radius("size", {
    curve: circle.curve,
    value: radius,
  });
  $.group("Shapes", [edge, length, circle, size]);
  return {
    edge: edge,
    circle: circle,
  };
});

